   "text": "Kimchi Fried Rice (Kimchi Bokkeumbap)",
   "size": "lg"
  },
  {
   "id": "meta",
   "component": "Row",
   "justify": "spaceBetween",
   "children": [
    "meta_time",
    "meta_serv"
   ]
  },
  {
   "id": "meta_time",
   "component": "Text",
   "text": "**Total time:** 20 minutes",
   "size": "sm"
  },
  {
   "id": "meta_serv",
   "component": "Caption",
   "text": "Serves 2"
  },
  {
   "id": "ing_head",
   "component": "Title",
   "text": "Ingredients",
   "size": "md"
  },
  {
   "id": "ings",
   "component": "List",
   "direction": "vertical",
   "marker": "bullet",
   "items": [
    {
     "label": "Day-old cooked short-grain rice",
     "value": "400 g (2 cups)"
    },
    {
     "label": "Aged kimchi, chopped",
     "value": "150 g"
    },
    {
     "label": "Kimchi juice",
     "value": "2 tbsp"
    },
    {
     "label": "Sesame oil",
     "value": "2 tbsp"
    },
    {
     "label": "Gochugaru (Korean chili flakes)",
     "value": "1 tsp"
    },
    {
     "label": "Soy sauce",
     "value": "1 tbsp"
    },
    {
     "label": "Sugar",
     "value": "1 tsp"
    },
    {
     "label": "Sesame seeds",
     "value": "1 tsp"
    },
    {
     "label": "Scallions, sliced",
     "value": "2"
    },
    {
     "label": "Eggs (one per serving)",
     "value": "2"
    },
    {
     "label": "Optional: diced spam, ham or tofu",
     "value": "100 g"
    }
   ]
  },
  {
   "id": "steps_head",
   "component": "Title",
   "text": "Steps",
   "size": "md"
  },
  {
   "id": "steps",
   "component": "List",
   "direction": "vertical",
   "marker": "number",
   "items": [
    {
     "label": "Prep",
     "description": "Chop the kimchi coarse and break up any clumps of cold rice with your hands.",
     "value": "2 min"
    },
    {
     "label": "Sauté the kimchi",
     "description": "Heat 1 tbsp sesame oil in a wok over medium-high heat. Fry the kimchi 2 minutes until caramelized; add gochugaru.",
     "value": "3 min"
    },
    {
     "label": "Add the rice",
     "description": "Add rice, kimchi juice and soy sauce. Toss 3–4 minutes, pressing and flipping, until grains are coated and slightly crispy.",
     "value": "4 min"
    },
    {
     "label": "Season",
     "description": "Stir in sugar and half the scallions. Taste and add a splash more kimchi juice if needed.",
     "value": "1 min"
    },
    {
     "label": "Fry the eggs",
     "description": "Push the rice aside, add remaining oil and fry the eggs sunny-side up, edges crisp.",
     "value": "3 min"
    },
    {
     "label": "Serve",
     "description": "Plate the rice, top with an egg, scatter sesame seeds and scallions. Drizzle sesame oil.",
     "value": "1 min"
    }
   ]
  },
  {
   "id": "tip",
   "component": "Caption",
   "text": "Cold, day-old rice fries best; fresh steamed rice turns mushy. Cooked times are illustrative.",
   "color": "secondary"
  },
  {
   "id": "followup",
   "component": "FollowUp",
